const rule = (r) => [r.id, r];
/** Every rule, by id. */
export const RULES = Object.fromEntries([
    rule({
        id: "model-invalid",
        category: "integrity",
        status: "verified_static_fact",
        severity: "high",
        title: "Declared model is unusable or contains a construct that is never evaluated",
        explanation: "The model could not be parsed, or uses !script, !plugin, a remote !include or workspace extends. Architecture Check never runs code or fetches content, so drift results may be incomplete.",
        action: "Fix the model, or move the construct out of the file Architecture Check reads.",
    }),
    rule({
        id: "model-reference-invalid",
        category: "integrity",
        status: "verified_static_fact",
        severity: "medium",
        title: "Declared model references an element that is not defined, or defines one twice",
        explanation: "A relationship, allowed dependency or containment names an undefined id, or an id is duplicated.",
        action: "Fix the reference or the duplicate id.",
    }),
    rule({
        id: "model-stale-reference",
        category: "integrity",
        status: "verified_static_fact",
        severity: "low",
        title: "Declared model references a file that does not exist",
        explanation: "An ADR or documentation path in the model points at nothing.",
        action: "Fix or remove the reference.",
    }),
    rule({
        id: "container-undeclared",
        category: "coverage",
        status: "verified_static_fact",
        severity: "medium",
        title: "Deployable unit is not in the declared model",
        explanation: "A compose service, Dockerfile or Kubernetes workload maps to no declared container. Verified when every declared container has commons.source, otherwise a hypothesis.",
        action: "Add it to the model (see the suggested snippet), or list it in ignore_containers.",
    }),
    rule({
        id: "element-source-missing",
        category: "coverage",
        status: "verified_static_fact",
        severity: "medium",
        title: "Declared element's commons.source matches nothing",
        explanation: "The path does not exist and no compose service, workload or Kubernetes Service has that name.",
        action: "Update the mapping, or remove the element if it no longer exists.",
    }),
    rule({
        id: "component-undeclared",
        category: "coverage",
        status: "hypothesis",
        severity: "low",
        title: "Source directory is not a declared component",
        explanation: "The container declares components, and this first-level source directory maps to none. Components follow a directory convention, so this is a hypothesis.",
        action: "Decide whether the directory is a component that belongs in the model.",
    }),
    rule({
        id: "relationship-undeclared",
        category: "relationships",
        status: "verified_static_fact",
        severity: "medium",
        title: "Observed dependency is not declared",
        explanation: "Imports, compose dependencies or host names in configuration connect two mapped elements, and no declared relationship covers them.",
        action: "Declare the relationship, or remove the dependency.",
    }),
    rule({
        id: "boundary-violation",
        category: "relationships",
        status: "verified_static_fact",
        severity: "high",
        title: "Observed dependency crosses a declared boundary",
        explanation: "The element declares commons.allowed-dependencies, and it depends on an element that is not allowed.",
        action: "Remove the dependency, or change the declared rule if the dependency is intended.",
    }),
    rule({
        id: "relationship-unobserved",
        category: "relationships",
        status: "unknown",
        severity: "info",
        title: "Declared relationship has no static evidence",
        explanation: "No import, compose dependency or configuration host name was found for it. Runtime calls and deploy-time configuration are invisible to static analysis, so this is unknown, not absent.",
        action: "Confirm the relationship still exists.",
    }),
    rule({
        id: "interface-unowned",
        category: "coverage",
        status: "verified_static_fact",
        severity: "medium",
        title: "API description is not inside any declared container",
        explanation: "An OpenAPI/AsyncAPI file lies outside the source paths of every mapped container.",
        action: "Attach it to its owning container with commons.source, or move it.",
    }),
    rule({
        id: "technology-mismatch",
        category: "technology",
        status: "hypothesis",
        severity: "low",
        title: "Declared technology differs from the build",
        explanation: "The declared technology names a known family, and the image the container is built from belongs to another. Multi-stage builds and sidecars can explain this.",
        action: "Update the declared technology, or check the build.",
    }),
    rule({
        id: "external-system-undeclared",
        category: "coverage",
        status: "hypothesis",
        severity: "low",
        title: "Vendor SDK is used but no external system is declared",
        explanation: "A mapped container imports a known third-party SDK, and no declared external system maps to the vendor.",
        action: "Declare the external system (and its data-handling notes).",
    }),
]);
